head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_digital.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF71005.xml";
scwin.vScrenTpCD = "";
scwin.clickBzProcsNo = "";
scwin.vMode = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명 : fn_SetParIsur2()
 * 설명    : 상장신청인 선택 팝업호출용
 **********************************************/
scwin.fn_SetParIsur2 = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
        scwin.fn_list_sync();
    }
};
scwin.fn_GetParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};
scwin.fn_list_sync = function() {
    var url = "/digital/DigitalSupport.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=digitalEduCompltList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&BZ_PROCS_NO=";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&CHRG_NM=" + txb_CHRG_NM.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.openChildForm = async function(mode, obj) {
    scwin.vMode = mode;
    if (scwin.vMode == "I") {
        scwin.clickBzProcsNo = "";
    } else {
        scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    }
    await $c.frame.CreateDialogFrame("DGSE_EDU", "/support/ULDSTF71005_P.gfm", " 교육이수현황 입력", 200, 100, 580, 500, "window");
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List, "예비심사리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_OpenDetail = async function(row) {
    var secugrpId;
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
        secugrpId = dts_List.getCellData(row, 'SECUGRP_ID');
    } else {
        //신규버튼 선택시
        scwin.clickBzProcsNo = ""; //초기화
        secugrpId = $c.stf.getObjectValue(rdo_SECUGRP_ID);
    }
    await $c.frame.CreateDialogFrame("BNEFCERT_PREEXAM", "/lstproc/ULDSTF05401.gfm", $c.lcd.fn_getSecuGrpNm(secugrpId) + " 예비심사관리", 200, 100, 560, 470, "window");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.btn_New_onclick = function() {
    scwin.openChildForm("I");
};
scwin.img_IsuSearch_onclick = function() {
    scwin.fn_SetPar = fn_SetParIsur2;
    scwin.fn_GetPar = fn_GetParIsur2;
    $c.lcd.fn_PopFindDigitalIsurAppl();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_ISUR_NM.setValue("");
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_list_sync();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.openChildForm("U", row);
};
scwin.txb_CHRG_NM_onkeyup = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_list_sync();
    }
};
